	})
	router.POST("/vulnerabilities/match", func(c *gin.Context) {
		matchVulnerabilities(c, st)
	})
	router.POST("/vulnerabilities/range-match", func(c *gin.Context) {
		matchByRange(c, st)
	})
	router.GET("/vulnerabilities/:id", func(c *gin.Context) {
