        if item.ID == "" || !vuln.ValidStatus(status) {
            respondInvalidInput(c)
            return
        }
        if _, duplicate := seen[item.ID]; duplicate {
            respondInvalidInput(c)
            return
        }
        seen[item.ID] = struct{}{}
        updates = append(updates, store.StatusUpdate{ID: item.ID, Status: status})
